import Foundation

/// The ⓘ text of every check (M1-00, B07): what it proves, numbered steps, and where it
/// happens (for the To do list). "Expected" comes from the check itself.
struct CheckGuide {
    enum Place: String, CaseIterable {
        case noScooter = "No scooter"
        case scooterHome = "Scooter at home"
        case ride = "On a ride"
        case passive = "Passive"
    }

    private static let routeStepSim = "Developer → Simulated scooter → Run on the real screens."

    let proves: String
    let steps: [String]
    let place: Place

    static func of(_ id: String) -> CheckGuide {
        all[id] ?? CheckGuide(proves: "—", steps: ["See the check's description."], place: .noScooter)
    }

    static let all: [String: CheckGuide] = [
        "h2": CheckGuide(proves: "Notification sounds are on, so the Kick-off chime can play (B10).",
                         steps: ["Developer → Permissions → step 1 (allow notifications with sounds).",
                                 "If Sounds still isn't on: step 6 → iPhone Settings → Notifications → CorckieApp → Sounds ON.",
                                 "Come back: the check updates by itself."], place: .noScooter),
        "h1": CheckGuide(proves: "The app has every permission v1 needs to record rides with the phone in your pocket.",
                         steps: ["Developer → Permissions.", "Do steps 1–6 top to bottom: notifications (with sounds), location While Using, then Always, motion, Bluetooth, sounds.",
