        "d3": CheckGuide(proves: "The backup folder still works after a phone restart.",
                         steps: ["Restart the phone.", "Developer → Backup folder → Write test file."], place: .noScooter),
        "d4": CheckGuide(proves: "The app notices when it crashed.",
